	if (receipt.state === "queued") return `메시지를 대기열 ${receipt.position}번에 추가했습니다.`;
	if (receipt.state === "uncertain") return `${receipt.reason} 자동 재시도하지 않습니다. /cancel로 서버 상태를 확인하세요.`;
	return receipt.reason;
}

